head.script:
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIndex;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gSchDate;
scwin.gSeq;
scwin.gChgBfafTpCd;
scwin.gDesignRsnCd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gISUR_CD;
scwin.gCOM_NM;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_5);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        MxTab_1.setSelectedTabIndex("1");
        cmb_CPOC_DESIGN_RSN_CD.BindColVal = "";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37710.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Grid_Tab1_OnLoadCompleted
 * @description dts_Grid_Tab1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_Tab1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.dts_Grid_Tab1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab1_OnLoadError
 * @description dts_Grid_Tab1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_Tab1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid_Tab1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37710.dts_Grid_Tab1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab2_OnLoadCompleted
 * @description dts_Grid_Tab2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_Tab2_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.dts_Grid_Tab2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab2_OnLoadError
 * @description dts_Grid_Tab2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_Tab2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid_Tab2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37710.dts_Grid_Tab2_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37710.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF37710.xml", SCREN_PROCS_TP_CD_07, '');
        if (scwin.gIndex === '1') {
            $c.data.downloadGridViewExcel(grd_Grid1, {fileName: "대상법인 현황", type: "8"});
        } else if (scwin.gIndex === '2') {
            $c.data.downloadGridViewExcel(grd_Grid2, {fileName: "대상법인 지정/해제 내역", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid1_OnDblClick
 * @description grd_Grid1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid1_OnDblClick = async function(row, colid) {
    try {
        scwin.gSeq = dts_Grid_Tab1.getCellData(Number(row), "CPOC_SEQ");
        scwin.gIsurCd = dts_Grid_Tab1.getCellData(Number(row), "ISUR_CD");
        scwin.gComAbbrv = dts_Grid_Tab1.getCellData(Number(row), "COM_ABBRV");
        scwin.gChgBfafTpCd = dts_Grid_Tab1.getCellData(Number(row), "CPOC_CHG_BFAF_TP_CD");
        scwin.gDesignRsnCd = dts_Grid_Tab1.getCellData(Number(row), "CPOC_DESIGN_RSN_CD");
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        } else if (colid === "DESIGN_RELEAS_BAS_DD") {
            if (scwin.gDesignRsnCd === "4" || scwin.gDesignRsnCd === "5" || scwin.gDesignRsnCd === "6") {
                const options = {
                    id: "ULDSTF37711",
                    title: "지정사유별 관리",
                    type: "browserPopup",
                    width: "610px",
                    height: "280px",
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("/dsclmgt/ULDSTF37711.gfm", options);
            } else if (scwin.gDesignRsnCd === "2") {
                const options = {
                    id: "ULDSTF35106",
                    title: "불성실공시법인(유)_STF35106",
                    type: "browserPopup",
                    width: "1300px",
                    height: "800px",
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("/dsclmgt/ULDSTF35106.gfm", options);
            } else if (scwin.gDesignRsnCd === "3") {
                await $c.frame.CreateDialogFrame("STF37704", "/dsclmgt/ULDSTF37704.gfm?ISUR_CD=" + scwin.gIsurCd + "&COM_NM=" + scwin.gComAbbrv, "관리종목지정(유)", 200, 100, 850, 530, "window");
            }
        } else if (colid === "CPOC_DESIGN_RSN_DSC") {
            const options = {
                id: "ULDSTF37711",
                title: "지정사유별 관리",
                type: "browserPopup",
                width: "610px",
                height: "280px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/dsclmgt/ULDSTF37711.gfm", options);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37710.grd_Grid1_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_Grid2_OnDblClick
 * @description grd_Grid2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid2_OnDblClick = function(row, colid) {
    try {
        scwin.gIsurCd = dts_Grid_Tab2.getCellData(Number(row), "ISUR_CD");
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.grd_Grid2_OnDblClick" });
    }
};

/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    try {
        scwin.gIndex = nIndex;
        if (scwin.gIndex === '2') {
            label_1.hide();
            edt_FromDate.hide();
            img_FromCal.hide();
            label_5.hide();
            edt_ToDate.hide();
            img_ToCal.hide();
            cmb_PeriodTp.hide();
            label_2.hide();
            edt_rel_FromDate.hide();
            img_rel_FromCal.hide();
            label_7.hide();
            edt_rel_ToDate.hide();
            img_rel_ToCal.hide();
            cmb_rel_PeriodTp.hide();
            label_8.hide();
            cmb_CPOC_DESIGN_RSN_CD.hide();
            label_3.show("");
            edt_SchDate3.show("");
            img_FromCal3.show("");
        } else {
            label_3.hide();
            edt_SchDate3.hide();
            img_FromCal3.hide();
            label_1.show("");
            edt_FromDate.show("");
            img_FromCal.show("");
            label_5.show("");
            edt_ToDate.show("");
            img_ToCal.show("");
            cmb_PeriodTp.show("");
            label_2.show("");
            edt_rel_FromDate.show("");
            img_rel_FromCal.show("");
            label_7.show("");
            edt_rel_ToDate.show("");
            img_rel_ToCal.show("");
            cmb_rel_PeriodTp.show("");
            label_8.show("");
            cmb_CPOC_DESIGN_RSN_CD.show("");
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37710.MxTab_1_OnSelChanged" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue(); // ;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_EMP_NO.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37710.btn_Close_onclick" });
    }
};

