 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    try {
        popUpCalendar2(edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        let vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.cmb_PeriodTp_onselchange" });
    }
};

/**
