 */
scwin.img_rel_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_rel_FromDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.img_rel_FromCal_onclick" });
    }
};

/**
 * @method
 * @name img_rel_ToCal_onclick
 * @description img_rel_ToCal 클릭 이벤트
