    }
};

/**
 * @method
 * @name img_FromCal3_onclick
 * @description img_FromCal3 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal3_onclick = function() {
    try {
        popUpCalendar2(edt_SchDate3);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.img_FromCal3_onclick" });
    }
};

/**
 * @method
 * @name cmb_rel_PeriodTp_onselchange
 * @description cmb_rel_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_rel_PeriodTp_onselchange = function() {
    try {
        let vTp = $c.cp.valueOfIndex(cmb_rel_PeriodTp, "VALUE", cmb_rel_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_rel_FromDate, edt_rel_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.cmb_rel_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37710.txb_isur_cd_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 페이지 로딩 시 필요한 변수 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 조회일자 오늘로 셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SchDate3.setValue(vCurDate);
    const arrCid = [{
        cid: "CPOC_DESIGN_RSN_CD",
        cnm: "cmb_CPOC_DESIGN_RSN_CD"
    }];
    let objCod;
    const sbmOptions3 = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체,";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (edt_FromDate.getValue() !== "") {
        // 일자 체크
        if (edt_FromDate.getValue().length < 8) {
            await $c.win.alert("일자 올바르게 입력하십시오.");
            edt_FromDate.focus();
            return;
        }
    }
    if (edt_ToDate.getValue() !== "") {
        // 일자 체크
        if (edt_ToDate.getValue().length < 8) {
            await $c.win.alert("일자 올바르게 입력하십시오.");
            edt_ToDate.focus();
            return;
        }
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    if (edt_rel_FromDate.getValue() !== "") {
        // 일자 체크
        if (edt_rel_FromDate.getValue().length < 8) {
            await $c.win.alert("일자 올바르게 입력하십시오.");
            edt_rel_FromDate.focus();
            return;
        }
    }
    if (edt_rel_ToDate.getValue() !== "") {
        // 일자 체크
        if (edt_rel_ToDate.getValue().length < 8) {
            await $c.win.alert("일자 올바르게 입력하십시오.");
            edt_rel_ToDate.focus();
            return;
        }
    }
    if ($c.stf.compareFromToDate2(edt_rel_FromDate, edt_rel_ToDate) === false) {
        return;
    }
    const vISUR_CD = txb_isur_cd.getValue();
    const vDEP_CD = cmb_DEP_CD.getValue();
    const vEMP_NO = cmb_EMP_NO.getValue();
    const vFIRST_ENFORCE_FROM = edt_FromDate.getValue();
    const vFIRST_ENFORCE_TO = edt_ToDate.getValue();
    const vDEEMED_RELEAS_FROM = edt_rel_FromDate.getValue();
    const vDEEMED_RELEAS_TO = edt_rel_ToDate.getValue();
    const vENFORCE_DD = edt_SchDate3.getValue();
    const vCPOC_DESIGN_RSN_CD = cmb_CPOC_DESIGN_RSN_CD.getValue();
    let url;
    if (scwin.gIndex === '1') {
        url += "&ISUR_CD=" + vISUR_CD;
        url += "&DEP_CD=" + vDEP_CD;
        url += "&EMP_NO=" + vEMP_NO;
        url += "&FIRST_ENFORCE_FROM=" + vFIRST_ENFORCE_FROM;
        url += "&FIRST_ENFORCE_TO=" + vFIRST_ENFORCE_TO;
        url += "&DEEMED_RELEAS_FROM=" + vDEEMED_RELEAS_FROM;
        url += "&DEEMED_RELEAS_TO=" + vDEEMED_RELEAS_TO;
        url += "&CPOC_DESIGN_RSN_CD=" + vCPOC_DESIGN_RSN_CD;
        url += "&SCREN_ID=" + "ULDSTF37710.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Grid_Tab1",
            action : "/ConfrmProcs.do",
            ref : "",
            target : "dts_Grid_Tab1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (scwin.gIndex === '2') {
        url += "&ISUR_CD=" + vISUR_CD;
        url += "&ENFORCE_DD=" + vENFORCE_DD;
        url += "&DEP_CD=" + vDEP_CD;
        url += "&EMP_NO=" + vEMP_NO;
        url += "&SCREN_ID=" + "ULDSTF37710.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
